{
  "name": "@dietrichgebert/ponytail",
  "version": "5.3.2",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": ["opencode-plugin", "opencode", "ponytail", "pi-package", "pi", "skills", "qoder"],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/DietrichGebert"
  },
  "homepage": "https://github.com/DietrichGebert/ponytail",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DietrichGebert/ponytail.git"
  },
  "bugs": {
    "url": "https://github.com/DietrichGebert/ponytail/issues"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "!pi-extension/test/",
    "scripts/uninstall.js",
    "scripts/cursor-hooks.js",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension"
  },
  "pi": {
    "extensions": ["./pi-extension/index.js"],
    "skills": ["./skills"]
  },
  "publishConfig": {
    "access": "public"
  }
}

# The impeccable runtime: one Cargo workspace next to the skill it powers.
# `cargo build --release -p impeccable` produces the engine binary the launcher
# (skill/scripts/impeccable) runs. See docs/ENGINE.md.
[workspace]
resolver = "2"
members = ["crates/*"]

[workspace.package]
version = "0.1.17"
edition = "2021"
license = "Apache-2.0"
publish = false

[workspace.dependencies]
impeccable-foundation = { path = "crates/foundation" }
impeccable-common = { path = "crates/common" }
impeccable-core = { path = "crates/core" }
impeccable-detect = { path = "crates/detect" }
impeccable-html = { path = "crates/html" }
impeccable-browser = { path = "crates/browser" }
impeccable-live = { path = "crates/live" }
impeccable-context = { path = "crates/context" }
impeccable-hook = { path = "crates/hook" }
impeccable-comp = { path = "crates/comp" }
impeccable-comp-verbs = { path = "crates/comp-verbs" }
impeccable-bundle = { path = "crates/bundle" }
serde = { version = "1", features = ["derive"] }
serde_json = { version = "1", features = ["preserve_order"] }
thiserror = "2"
regex = "1"
once_cell = "1"

# Dev and test builds keep file:line backtraces and drop the rest of the
# debuginfo, which is most of a target dir's size. Dependencies carry none.
[profile.dev]
debug = "line-tables-only"

[profile.dev.package."*"]
debug = false

[profile.release]
opt-level = 3
lto = "fat"
codegen-units = 1
strip = true
panic = "abort"

{
	"name": "linkswift",
	"version": "1.1.3.1",
	"description": "一个基于 JavaScript 的网盘文件下载地址获取工具",
	"main": "eslint.config.js",
	"scripts": {
		"test": "echo \"Error: no test specified\" && exit 1",
		"check": "npx eslint . --fix"
	},
	"repository": {
		"type": "git",
		"url": "git+https://github.com/hmjz100/LinkSwift.git"
	},
	"keywords": [
		"linkswift",
		"link",
		"swift",
		"download",
		"file",
		"address",
		"get"
	],
	"author": "hmjz100",
	"license": "AGPL-3.0",
	"type": "commonjs",
	"bugs": {
		"url": "https://github.com/hmjz100/LinkSwift/issues"
	},
	"homepage": "https://github.com/hmjz100/LinkSwift#readme",
	"devDependencies": {
		"@eslint/js": "^10.0.1",
		"eslint": "^10.6.0"
	},
	"dependencies": {
		"@eslint/js": "^10.0.1",
		"eslint": "^10.6.0"
	}
}

{
  "name": "marble-taxonomy",
  "version": "1.0.0",
  "description": "An open, graph-structured taxonomy of primary/elementary learning.",
  "private": true,
  "type": "module",
  "license": "(ODbL-1.0 AND CC-BY-SA-4.0)",
  "homepage": "https://withmarble.com",
  "scripts": {
    "validate": "node scripts/validate.mjs",
    "test": "node --test scripts/*.test.mjs"
  }
}

[workspace]
members = [
    # -- core
    "crates/uzu-engine",
    "crates/uzu-engine-macros",
    # -- benches
    "scripts/benchmarks/engine-uzu",
    # -- apps
    "apps/mirai-gui/desktop",
    # --- to be rewritten
    "crates/legacy/bindings-types",
    "crates/legacy/bindings",
    "crates/legacy/shoji",
    "crates/legacy/backend-remote",
    "crates/legacy/json-transform",
    "crates/legacy/token-stream-parser",
    "crates/legacy/hanashi",
    "crates/legacy/nagare",
    "crates/legacy/nagare-macros",
    "crates/legacy/download-manager",
    "crates/legacy/mock-registry",
    "crates/legacy/uzu",
    "crates/legacy/cli",
    "crates/legacy/cli-tools",
    "crates/legacy/keisoku",
    "crates/legacy/kanka",
    "crates/legacy/kiban",
]
resolver = "3"

[workspace.package]
edition = "2024"
rust-version = "1.98"
