json-transform = { path = "crates/legacy/json-transform", default-features = false }
token-stream-parser = { path = "crates/legacy/token-stream-parser", default-features = false }
hanashi = { path = "crates/legacy/hanashi", default-features = false }
nagare = { path = "crates/legacy/nagare", default-features = false }
nagare-macros = { path = "crates/legacy/nagare-macros" }
download-manager = { path = "crates/legacy/download-manager", default-features = false }
mock-registry = { path = "crates/legacy/mock-registry", default-features = false }
keisoku = { path = "crates/legacy/keisoku", default-features = false }
kanka = { path = "crates/legacy/kanka", default-features = false }
kiban = { path = "crates/legacy/kiban", default-features = false }
uzu = { path = "crates/legacy/uzu", default-features = false }
