objc2 = "0.6.5"
objc2-foundation = "0.3.2"
objc2-core-foundation = "0.3.2"
objc2-io-kit = { version = "0.3.2", default-features = false, features = ["libc", "ps"] }
obfstr = "0.4.6"
metal = { package = "mtl-rs", version = "0.3.0" }
block2 = "0.6.2"
bytemuck = "1.25.2"
bytesize = "2.7.0"
xxhash-rust = "0.8.19"
num-traits = "0.2.19"
